package com.sakalti.modifier;
import net.minecraft.nbt.NbtCompound; import net.minecraft.entity.LivingEntity; import net.minecraft.world.World; import net.minecraft.item.ItemStack; import java.util.Random;
import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class LuckyModifier extends Modifier {private static final Random RANDOM=new Random();
 @Override public void onInventoryTick(IToolStackView tool,int level,World world,LivingEntity e,int slot,boolean selected,boolean correct,ItemStack stack){if(world==null||world.isClient||tool==null||stack==null||!correct||tool.isBroken())return;NbtCompound tag=stack.getOrCreateNbt();int timer=tag.getInt("SakaltiLuckyTimer"),limit=tag.getInt("SakaltiLuckyLimit");if(limit<20||limit>7200)limit=20+RANDOM.nextInt(7181);timer++;if(timer>=limit){tool.setDamage(0);timer=0;limit=20+RANDOM.nextInt(7181);}tag.putInt("SakaltiLuckyTimer",timer);tag.putInt("SakaltiLuckyLimit",limit);stack.setNbt(tag);}}